// w8002-gc-truncate
// Daily GC for /miru-data/pending_callbacks.jsonl.
// Drops rows older than 48h, pair-aware: groups by token, drops both intent
// and decided rows for a token when the newer timestamp in the group is past
// the cutoff. Avoids orphaning a 'decided' whose 'intent' aged out, which
// would degrade w7006-lookup-pending's reverse scan.
//
// Atomic rewrite: write survivors to .tmp, then renameSync. If anything
// throws before the rename, the original file stays intact and the error
// bubbles up to n8n's error trigger -> W1 error handler.
//
// Note: the HMAC replay window in w7004-hmac-validate is ~10 min, so 48h is
// generous for callback validity but reasonable audit/observability margin.
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const TMP = PENDING + '.tmp';
const CUTOFF_HOURS = 48;

const t0 = Date.now();
const cutoffMs = t0 - CUTOFF_HOURS * 3600 * 1000;

let raw = '';
if (fs.existsSync(PENDING)) {
  raw = fs.readFileSync(PENDING, 'utf8');
}

const lines = raw.split('\n');
const records = [];
for (let i = 0; i < lines.length; i++) {
  const text = lines[i];
  if (text === '') continue;
  let parsed = null;
  try { parsed = JSON.parse(text); } catch (e) { /* malformed: keep verbatim */ }
  let token = null;
  let ts = null;
  if (parsed && typeof parsed === 'object') {
    token = parsed.token || null;
    if (parsed.kind === 'intent' && parsed.intent_written_at) {
      const t = Date.parse(parsed.intent_written_at);
      if (!Number.isNaN(t)) ts = t;
    } else if (parsed.kind === 'decided' && parsed.decided_at) {
      const t = Date.parse(parsed.decided_at);
      if (!Number.isNaN(t)) ts = t;
    }
  }
  records.push({ text, token, ts });
}

const tokenMaxTs = new Map();
for (const r of records) {
  if (r.token == null || r.ts == null) continue;
  const prev = tokenMaxTs.get(r.token);
  if (prev == null || r.ts > prev) tokenMaxTs.set(r.token, r.ts);
}

const droppedTokens = new Set();
for (const [token, maxTs] of tokenMaxTs) {
  if (maxTs < cutoffMs) droppedTokens.add(token);
}

const kept = [];
let rowsDropped = 0;
for (const r of records) {
  if (r.token != null && r.ts != null && droppedTokens.has(r.token)) {
    rowsDropped++;
    continue;
  }
  kept.push(r.text);
}

const rowsBefore = records.length;
const rowsAfter = kept.length;

fs.writeFileSync(TMP, kept.length > 0 ? kept.join('\n') + '\n' : '');
fs.renameSync(TMP, PENDING);

return [{ json: {
  rows_before: rowsBefore,
  rows_after: rowsAfter,
  rows_dropped: rowsDropped,
  tokens_dropped: droppedTokens.size,
  cutoff_hours: CUTOFF_HOURS,
  cutoff_iso: new Date(cutoffMs).toISOString(),
  runtime_ms: Date.now() - t0
}}];

// w8003-log-history
// Append a single GC summary row to /miru-data/routing_history.jsonl.
// Shape patterned on the minimal 'skipped-dedupe' precedent: timestamp,
// trace_id, outcome + descriptive fields. No ranking fields.
const fs = require('fs');
const crypto = require('crypto');
const HISTORY = '/miru-data/routing_history.jsonl';

const summary = $input.item.json;
const trace_id = 'w8-gc-' + crypto.randomBytes(8).toString('hex');

const row = {
  timestamp: new Date().toISOString(),
  trace_id,
  outcome: 'gc-callbacks',
  workflow: 'w8',
  rows_before: summary.rows_before,
  rows_after: summary.rows_after,
  rows_dropped: summary.rows_dropped,
  tokens_dropped: summary.tokens_dropped,
  cutoff_hours: summary.cutoff_hours,
  cutoff_iso: summary.cutoff_iso,
  runtime_ms: summary.runtime_ms
};

fs.appendFileSync(HISTORY, JSON.stringify(row) + '\n');

return { json: { ...summary, _logged: true, trace_id } };
